import '../domain/notification_repository.dart';import '../domain/notification_entity.dart';import 'notification_datasource.dart';class NotificationRepositoryImpl implements NotificationRepository{NotificationRepositoryImpl(this.source);final NotificationDatasource source;Future<List<NotificationEntity>>list()=>source.list().then((x)=>x.map((e)=>NotificationEntity.fromJson(e)).toList());Future<int>unreadCount()=>source.unreadCount();Future<NotificationEntity>markRead(String id)=>source.read(id).then(NotificationEntity.fromJson);}
